$('comments-list').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.reply||b.dataset.heart||b.dataset.pin||b.dataset.deleteComment||b.dataset.reportComment||b.dataset.sendReply||b.dataset.editComment;if(b.dataset.reply){$('reply-'+id).classList.toggle('hidden');return;}if(b.dataset.sendReply){const text=$('reply-text-'+id).value.trim();if(text)await postComment(text,id);return;}if(b.dataset.editComment){const {data:comment}=await sb.from('comments').select('content').eq('id',id).single();const revised=prompt('Edit your comment',comment?.content||'');if(revised&&revised.trim()){const {error}=await sb.from('comments').update({content:revised.trim()}).eq('id',id);if(error)notify(error.message);await loadComments();}return;}if(b.dataset.deleteComment){if(confirm('Delete this comment?')){const {error}=await sb.from('comments').delete().eq('id',b.dataset.deleteComment);if(error)notify(error.message);await loadComments();}return;}if(b.dataset.heart||b.dataset.pin){const field=b.dataset.heart?'creator_hearted':'is_pinned';const {data}=await sb.from('comments').select(field).eq('id',id).single();const {error}=await sb.from('comments').update({[field]:!data[field]}).eq('id',id);if(error)notify(error.message);await loadComments();return;}if(b.dataset.reportComment){state.commentReportId=id;$('comment-report-label').textContent='Report comment #'+id;openModal('video-report-modal');}});
async function postComment(content,parentId=null){if(!state.user){notify('Start a guest session or sign in to comment.');return;}if(!state.activeVideo||!content.trim())return;const {error}=await sb.from('comments').insert({video_id:state.activeVideo.id,user_id:state.user.id,content:content.trim(),parent_id:parentId});if(error){notify('Comment could not be posted: '+error.message);return;}if(!parentId)$('comment-input').value='';else{const replyInput=$('reply-text-'+parentId);if(replyInput)replyInput.value='';}await loadComments();}
$('comment-submit').addEventListener('click',()=>postComment($('comment-input').value));$('comment-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('comment-submit').click();}});$('comment-report-submit').addEventListener('click',async()=>{const {error}=await sb.from('content_reports').insert({reporter_id:state.user.id,comment_id:state.commentReportId,reason:'comment_report'});if(error)notify(error.message);else notify('Comment reported.');closeModal('video-report-modal');});
